import { FileItem, FileLikeObject, FileUploader, FileUploaderOptions } from 'ng2-file-upload';
import { MessageService } from 'espd-common/i18n';
import { EspdControl } from 'espd-common/forms/api';
import { SessionService } from 'espd-common/session';


export interface FileUploadHandler {
	control: EspdControl;
	failedFilter?: 'fileSize' | 'mimeType' | 'queueLimit';
	uploadErrorMessage?: string;
	addImage(item: FileItem, response: any): void;
}

export class ESFileUploader extends FileUploader {

	constructor(
		private handler: FileUploadHandler,
		private sessionService: SessionService,
		private messageService: MessageService,
		options: FileUploaderOptions) {
		super(options);
	}

	onAfterAddingFile(_: FileItem): void {
		this.handler.failedFilter = undefined;
		this.handler.uploadErrorMessage = undefined;
	}

	onCompleteItem(): void {
		if (this.handler.control) {
			this.handler.control.markAsTouched();
		}
	}

	onSuccessItem(item: FileItem, response: any): void {
		this.handler.addImage(item, response);
	}

	onCancelItem(item: FileItem): void {
		item.remove();
	}

	onWhenAddingFileFailed(_: FileLikeObject, filter: any): void {
		this.handler.failedFilter = filter.name;
		if (this.handler.control) {
			this.handler.control.markAsTouched();
		}
	}

	onErrorItem(item: FileItem, response: any, status: number): void {
		if (status === 401) {
			this.sessionService.lostSession();
		}
		this.handler.uploadErrorMessage = response.message || this.messageService.get('common.imageUpload.error');
		item.remove();
	}

	protected _transformResponse(response: string): string {
		return response ? JSON.parse(response) : response;
	}
}