import { CdkDragDrop, DragDropModule, moveItemInArray } from '@angular/cdk/drag-drop';
import { NgClass } from '@angular/common';
import {
	Component, ElementRef, forwardRef, Injector, Input, OnChanges, OnInit, Optional,
	QueryList, SimpleChanges, ViewChild, ViewChildren
} from '@angular/core';
import { AbstractControl, ReactiveFormsModule } from '@angular/forms';
import { AlertModule } from 'espd-common/alert';
import { ButtonComponent } from 'espd-common/button';
import {
	ControlNameModule, espdAbstractInputComponentInjectionToken,
	EspdAbstractSizeableInputDirective, EspdFormArray, EspdFormControl, EspdFormGroup
} from 'espd-common/forms/api';
import { ImageUploadConfig } from 'espd-common/forms/image-upload/config';
import { InputScaffoldComponent } from 'espd-common/forms/input-scaffold';
import { MessageModule } from 'espd-common/i18n';
import { IconDirective } from 'espd-common/icon';
import { SessionService } from 'espd-common/session';
import { FileItem, FileUploadModule } from 'ng2-file-upload';
import { CookieService } from 'ngx-cookie-service';
import { ESFileUploader, FileUploadHandler } from './file-uploader.class';

type ImageSize = string;

const filterErrorMessageKeys = {
	fileSize: 'common.imageUpload.error.tooBig',
	mimeType: 'common.imageUpload.error.invalidFileType',
	queueLimit: 'common.imageUpload.error.limit'
};

export interface MediaFormModel {
	[K: string]: AbstractControl<any>;
	mediaId: EspdFormControl<number>;
	name: EspdFormControl<string>;
	contentUrl: EspdFormControl<string>;
}

class Image {
	constructor(public formGroup: EspdFormGroup<MediaFormModel>, private config: ImageUploadConfig) { }

	public get url(): string {
		const value = this.formGroup.value;
		if (value.contentUrl) {
			return value.contentUrl;
		} else if (value.mediaId) {
			return `${this.config.url}/${value.mediaId}`;
		} else {
			return `${this.config.url}/file?name=${value.name}`;
		}
	}
}

@Component({
	selector: 'espd-image-upload',
	templateUrl: 'image-upload.component.html',
	styleUrl: 'image-upload.component.scss',
	providers: [{ provide: espdAbstractInputComponentInjectionToken, useExisting: forwardRef(() => ImageUploadComponent) }],
	imports: [
		FileUploadModule,
		ReactiveFormsModule,
		AlertModule,
		ButtonComponent,
		ControlNameModule,
		DragDropModule,
		IconDirective,
		InputScaffoldComponent,
		MessageModule,
		NgClass
	]
})
export class ImageUploadComponent extends EspdAbstractSizeableInputDirective<EspdFormArray<EspdFormGroup<MediaFormModel>>> implements OnInit, OnChanges, FileUploadHandler {

	@Input() public imageSize?: ImageSize;
	@Input() public uploadLimit: number = 1;
	@Input() public allowedMimeTypes?: string[];
	@Input() public defaultImageUrl?: string;
	@Input() public showImagePreview: boolean = true;
	@Input() public ordered: boolean = false;

	@ViewChild('input')
	public input!: ElementRef;

	@ViewChildren('listItem')
	private listItems!: QueryList<ElementRef>;

	public uploader: ESFileUploader;
	public failedFilter?: 'fileSize' | 'mimeType' | 'queueLimit';
	public uploadErrorMessage?: string;
	public hasFileOver: boolean = false;
	public images: Array<Image> = [];

	constructor(
		sessionService: SessionService,
		cookieService: CookieService,
		@Optional() private config: ImageUploadConfig,
		injector: Injector
	) {
		super(injector);
		if (!this.config) {
			this.config = new ImageUploadConfig();
		}

		this.uploader = new ESFileUploader(this, sessionService, this.messageService, {
			url: `${this.config.url}/upload`,
			isHTML5: true,
			autoUpload: true,
			queueLimit: this.calculateQueueLimit(),
			maxFileSize: this.config.maxFileSize,
			allowedMimeType: this.config.allowedMimeTypes,
			headers: [{
				name: 'Accept',
				value: 'application/json'
			}, {
				name: 'X-Requested-With',
				value: 'XMLHttpRequest'
			}, {
				name: 'X-XSRF-TOKEN',
				value: cookieService.get('XSRF-TOKEN')
			}]
		});
	}

	public get isDisabled(): boolean {
		return this.disabled || this.control.disabled;
	}

	public get failedFilterMessage(): string {
		return this.failedFilter ? this.messageService.get(filterErrorMessageKeys[this.failedFilter], this.uploadLimit) : '';
	}

	private get configuredMimeTypes(): string[] {
		return this.allowedMimeTypes ? this.allowedMimeTypes : this.config.allowedMimeTypes;
	}

	public get mimeTypesString(): string {
		return this.configuredMimeTypes.join(',');
	}

	public get imagesUploading(): FileItem[] {
		return this.uploader.queue.filter(i => i.isUploading);
	}

	public ngOnInit(): void {
		super.ngOnInit();

		if (!this.control) {
			this.control = new EspdFormArray<EspdFormGroup>([]);
		}
		this.images = this.control.controls.map(group => new Image(group as EspdFormGroup, this.config));
		this.updateImageUploader();
	}

	public ngOnChanges(changes: SimpleChanges): void {
		super.ngOnChanges(changes);
		this.updateImageUploader();
	}

	public calculateQueueLimit(): number | undefined {
		if (this.uploadLimit > 0) {
			return this.uploadLimit - this.images.length;
		}
		return undefined;
	}

	public onLabelKeypress(event: KeyboardEvent): void {
		if (event.key.toLowerCase() === 'enter') {
			this.input.nativeElement.click();
		}
	}

	public fileOver(isOver: boolean): void {
		this.hasFileOver = isOver && !this.disabled;
	}

	public removeImage(image: Image): void {
		if (this.disabled) {
			return;
		}

		const formArray = this.control as EspdFormArray;
		formArray.removeAt(formArray.controls.indexOf(image.formGroup));
		formArray.markAsDirty();
		formArray.markAsTouched();

		this.images.splice(this.images.indexOf(image), 1);
		this.updateImageUploader();
	}

	public addImage(item: FileItem, response: any): void {
		if (this.disabled) {
			return;
		}

		this.uploader.removeFromQueue(item);
		const formArray = this.control as EspdFormArray;
		const group = new EspdFormGroup<MediaFormModel>({
			name: new EspdFormControl(response.name),
			mediaId: new EspdFormControl(response.mediaId),
			contentUrl: new EspdFormControl(response.url),
			width: new EspdFormControl(response.width)
		});
		this.images.push(new Image(group, this.config));
		formArray.push(group);
		formArray.markAsDirty();
		formArray.markAsTouched();
		this.updateImageUploader();
	}

	public stopEventIfDisabled(event: MouseEvent): void {
		if (this.disabled) {
			event.preventDefault();
			event.stopImmediatePropagation();
		}
	}

	private updateImageUploader(): void {
		this.uploader.setOptions({
			url: `${this.config.url}/upload?size=${this.imageSize ?? ''}`,
			allowedMimeType: this.configuredMimeTypes,
			queueLimit: this.calculateQueueLimit(),
		});
	}

	/*
	// Drag and Drop
	*/
	public reorderDroppedItem(event: CdkDragDrop<any[]>): void {
		if (event.previousIndex !== event.currentIndex) {
			this.moveItem(event.previousIndex, event.currentIndex);
		}
	}

	public moveItemUp(index: number, event: Event): void {
		if (this.ordered && index > 0) {
			this.moveItem(index, index - 1);
		}
		event.preventDefault();
	}

	public moveItemDown(index: number, event: Event): void {
		const value = this.control.value as any[];
		if (this.ordered && index < value.length) {
			this.moveItem(index, index + 1);
		}
		event.preventDefault();
	}

	private moveItem(previousIndex: number, currentIndex: number) {
		const value = this.control.value as any[];
		moveItemInArray(value, previousIndex, currentIndex);
		moveItemInArray(this.images, previousIndex, currentIndex);

		setTimeout(() => {
			this.listItems.get(currentIndex)?.nativeElement.focus();
		});
	}

	public focus(_target: 'control' | 'container' = 'control'): void {
		throw new Error('Method not implemented.');
	}
}